    case "roof": {
      if (!pos[0]) die("roof <in.nbt> <out.nbt> --style hip|gable|mansard|... (or --spec roof.json) | roof <in.nbt> --detect");
      const g = load(pos[0]);
      const spec = flags.spec ? JSON.parse(readFileSync(flags.spec, "utf8")) : {};
      const nums = (v) => String(v).split(",").map(Number);
      const FACE = { n: "north", s: "south", e: "east", w: "west" };
      const keep = [...(spec.keep || []), ...(flags.keep ? [nums(flags.keep)].map((a) => ({ from: a.slice(0, 3), to: a.slice(3, 6) })) : [])];
      if (flags.detect) {
        const d = detectEave(g, { keep });
        const r = { file: pos[0], eave: d.eave, roofStartsAt: d.y, footprint: d.rects, area: d.area, wallTops: d.wallTops };
        if (flags.json) return out(r);
        console.log(`${pos[0]}: eave (top wall course) y=${d.eave}, roof starts at y=${d.y}; footprint ${d.area} cells as ${d.rects.length} rect(s): ${d.rects.map((r) => `[${r}]`).join(" ")}`);
        console.log(`  perimeter wall tops (y: columns): ${Object.entries(d.wallTops).map(([y, n]) => `${y}:${n}`).join("  ")}`);
        return;
      }
      if (!pos[1] && !flags["dry-run"]) die("roof <in.nbt> <out.nbt> ... (or --dry-run)");
      const o = { ...spec, keep };
      for (const k of ["preset", "style", "pitch", "eave", "material", "trim", "ridge", "gable", "verge", "hips", "soffit", "low", "ridgeAxis", "front"]) if (flags[k] != null && flags[k] !== true) o[k] = flags[k];
      if (flags["no-contrast"]) o.contrast = false;
      if (flags.why != null && flags.why !== true) o.why = String(flags.why);
      if (flags.overhang != null && flags.overhang !== true) {
        const v = nums(flags.overhang);
        o.overhang = v.length === 4 ? { north: v[0], south: v[1], east: v[2], west: v[3] } : v[0];
        if (v.some((n) => !Number.isFinite(n) || n < 0)) die(`--overhang takes n or n,s,e,w (got ${flags.overhang})`);
        if (v.some((n) => n === 0) && !o.why) die("--overhang 0 removes the eave (no shadow line, no barge); give --why \"<reason from the concept>\" or use 1+");
      }
      if (flags.texture != null && flags.texture !== true) {
        if (flags.texture === "none") { o.texture = false; if (!o.why) die("--texture none makes a single flat roof plane; give --why \"<reason from the concept>\" or pick a palette"); }
