// Writes parts/<name>.mjs stubs: the scope (and plan.md's PARTS line for the five structural parts), verbatim.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";

const dir = "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/villa-haiku";
const parts = JSON.parse(readFileSync("/tmp/gen-parts/parts.json", "utf8"));
const planLines = readFileSync(`${dir}/plan.md`, "utf8").split("\n");
const partsLine = (name) => planLines.find((l) => new RegExp(`^\\d\\. \\*\\*${name}\\*\\*`).test(l));

mkdirSync(`${dir}/parts`, { recursive: true });
for (const p of parts) {
  const entry = partsLine(p.name);                       // only the five structural parts have a PARTS line
  const comment = ["/*", p.scope, ...(entry ? ["", entry] : []), "*/"].join("\n");
  const src = `// STUB: builds nothing yet. Delete this line when the part is built (make.sh skips the roof step while shell is a stub).\n${comment}\n\nexport function build(g) {}\n`;
  writeFileSync(`${dir}/${p.module}`, src);
  console.log(`${p.module}: scope ${p.scope.length} chars${entry ? ", PARTS line" : ""}`);
}

